-- IG M7.13 EKB lessons: record actual blockers and prevention without adding controls.
-- Git first; execute identical migration after merge; no production activation.
-- New codes are append-only and retry-idempotent; existing knowledge is not overwritten.
DO $ekb$
DECLARE n_existing integer; n_new integer; n_old integer; old_keys text[];
BEGIN
 SELECT count(*) INTO n_existing FROM public.lf_error_knowledge
 WHERE codigo=ANY(ARRAY['IG-M713-UNBLOCK-NOT-UNIT-CLOSURE-001','IG-M713-MATERIAL-ASSERTION-RECEIPT-001','IG-M713-FUSED-MUTATION-PROVIDER-001','IG-M713-ASOF-UPSTREAM-NOT-MISSING-001','IG-M713-EXPLAINED-DIVERGENCE-HOLD-001','IG-M713-PYTHON-ONE-RUN-TWELVE-CASES-001','IG-M713-BLOCKER-COUNT-DYNAMIC-001']);
 IF n_existing<>0 THEN RAISE EXCEPTION 'IG_M713_EKB_CODES_ALREADY_EXIST_%',n_existing; END IF;
 SELECT count(*) INTO n_old FROM public.lf_error_knowledge
 WHERE codigo IN ('ENGINEERING-AUTHORITY-SELF-REPAIR-CIRCULAR-001','ENGINEERING-BLOCKER-DUAL-SCOPE-REPAIR-001');
 IF n_old<>2 THEN RAISE EXCEPTION 'IG_M713_EKB_BASE_KNOWLEDGE_MISSING_%',n_old; END IF;
 INSERT INTO public.lf_error_knowledge(id,codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,frecuencia,primera_vez,ultima_vez,lote_origen,pr,estado,evidencia,created_at,updated_at,lifecycle_phase,consumer_role,root_cause_family,detectability,source_context,source_ref)
 VALUES (
 gen_random_uuid(),'IG-M713-UNBLOCK-NOT-UNIT-CLOSURE-001','ENGINEERING_CLOSURE','Quitar el bloqueo de gobernanza no completa los checkpoints materiales','M7.13 permaneció IN_PROGRESS 20% 1/5 tras resolver el pin circular; el trabajo de construcción de los tres controles, adversariales y recibo seguía sin ejecutarse.','Se confundió recuperación del autorizador y actualización de contrato con ejecución y cierre de la unidad; el ledger exige transiciones independientes por checkpoint.','UNBLOCKED_AUTHORIZER != COMPLETED_ENGINEERING_UNIT','Después de reparar el contrato y la gobernanza, re-bootstrap; ejecutar todos los checkpoints vigentes por su naturaleza, persistir recibos y transiciones usando fn_engineering_checkpoint_transition_v1; comprobar status DONE, 5/5 y bloqueos=0. No declarar DONE basado en merge o elegibilidad.','Readback final work PAULO-085 DONE, M7.13 5/5 y terminal STOP_TERMINAL_DONE; checkpoints 2 a 5 completados tras PR 2111, 2113, 2115, 2119.','HIGH',1,now(),now(),'IG_CURATOR_VALIDATOR_REFACTOR_V2','2111,2113,2115,2119','VALIDATED_TESTED','supabase://programacion.engineering_work_items/246; Git PR 2111/2113/2115/2119; fn_engineering_unit_bootstrap_v3 M7.13 DONE 100%',now(),now(),'EXECUTION',ARRAY['ENGINEERING_EXECUTOR','ENGINEERING_SCHEDULER']::text[],'PROCESS_VS_RESULT_CONFLATION','LIVE_READBACK_AND_NEGATIVE_TEST','M7.13 PAULO-085 completed 5/5, no IG production release','programacion.fn_engineering_unit_bootstrap_v3'),
(
 gen_random_uuid(),'IG-M713-MATERIAL-ASSERTION-RECEIPT-001','ENGINEERING_VALIDATION','DONE material requiere recibo de aserción vinculado al contrato vigente','Checkpoint CRITERIA_AS_CONTROLS rechazó DONE con ENGINEERING_MATERIAL_ASSERTION_RECEIPT_REQUIRED aun con migración Git y DB aplicada.','La transición exige contract_sha256, assertion_receipt, SHA del recibo y timestamp; no basta un link al PR ni un reporte textual.','MATERIAL_CHECKPOINT_DONE_WITHOUT_CANONICAL_ASSERTION_RECEIPT','Realizar pruebas positivas y negativas, llamar fn_engineering_checkpoint_assertion_record_v1 con observed que satisfaga el pass_when exacto y evidencia real; leer receipt y luego transicionar mediante fn_engineering_checkpoint_transition_v1. Nunca mutar directamente el checkpoint ni debilitar trigger.','Recibo CRITERIA_AS_CONTROLS assertion sha 9e4a212a51fbf2b87ab27c9cc21ba55ee24f828ef5610e1aa6ae3c08842864a6; transición 20% a 40% registrada; trigger conservado.','HIGH',1,now(),now(),'IG_CURATOR_VALIDATOR_REFACTOR_V2','2111','VALIDATED_TESTED','supabase://programacion.engineering_work_checkpoints/690; fn_guard_engineering_material_checkpoint_done_v1; github://cristhianlujan/claude-persona-lf-patch/pull/2111',now(),now(),'EXECUTION',ARRAY['ENGINEERING_EXECUTOR','VALIDATOR']::text[],'MISSING_EXECUTION_EVIDENCE','LIVE_READBACK_AND_NEGATIVE_TEST','M7.13 PAULO-085 completed 5/5, no IG production release','programacion.fn_engineering_checkpoint_assertion_record_v1'),
(
 gen_random_uuid(),'IG-M713-FUSED-MUTATION-PROVIDER-001','DEPENDENCY_CURRENTNESS','M7.7 fusionada no debe solicitarse como ejecutor de pruebas de mutación','Contrato M7.13 refería suite de M7.7, pero M7.7 FUSED sin work_item_id; su ejecutor vigente es M4.9/PAULO-063 DONE.','El binding usaba una referencia histórica a unidad fusionada en vez de resolver su target efectivo. El primer evaluador exigía metadatos y una aserción IG_KNOWN_FALSE_PASS_REJECTED inexistentes en el recibo verdadero.','FUSED_ALIAS_MISTAKEN_FOR_EXECUTABLE_TEST_AUTHORITY','Antes de fijar test_code, suite_code y unidad proveedora, resolver disposition FUSED y remap_action; consumir suite real M4.9 con 10/10 aserciones tipadas detected=true y false_pass=false y verificar bundle VERIFIED; inyectar false_pass=true con ROLLBACK para demostrar bloqueo.','M4.9 suite 980a2228-24ad-4d14-a63c-e8fbb251b783 10/10 VERIFIED, al mutar false_pass a true pasa a BLOCKED; restauración ROLLBACK sin residuo. PR 2115 fusionado.','HIGH',1,now(),now(),'IG_CURATOR_VALIDATOR_REFACTOR_V2','2115','VALIDATED_TESTED','supabase://public.lf_test_suite_runs/980a2228-24ad-4d14-a63c-e8fbb251b783; github://cristhianlujan/claude-persona-lf-patch/pull/2115',now(),now(),'EXECUTION',ARRAY['ENGINEERING_EXECUTOR','VALIDATOR','CONTRACT_COMPILER']::text[],'FUSED_ALIAS_CURRENTNESS','LIVE_READBACK_AND_NEGATIVE_TEST','M7.13 PAULO-085 completed 5/5, no IG production release','programacion.engineering_plan_units M7.7 FUSED -> M4.9'),
(
 gen_random_uuid(),'IG-M713-ASOF-UPSTREAM-NOT-MISSING-001','SOURCE_CURRENTNESS','Bundle M9.0 marcado como inexistente cuando ya estaba DONE y tenía recibo','Source pack de checkpoint QUAL_RECEIPT_READBACK declaraba ''M9.0 aún inexistente'' pese a unidad M9.0 PAULO-148 DONE 5/5 y provenance receipt 187 VERIFIED.','Snapshot estático de dependencias no refrescado contra la autoridad viva ni distinguiendo recibo histórico as-of de release actual.','STALE_MISSING_UPSTREAM_REFERENCE_PERSISTS_AFTER_LIVE_DONE','Consultar work_item M9.0 y provenance_receipts antes de bloquear, reconciliar missing_typed no bloqueante y registrar SHA as-of exacto (no presentarlo como evidencia release actual). El checkpoint del constructor verifica el recibo disponible sin exigir publicación.','M9.0/PAULO-148 DONE 5/5; receipt 187 sha db84f4ab3cdcc0fe3dcdd463be70ad9b4c96ec7beb9be9cc56b9d344793e7f2f coincide con payload manifest; head as-of 5a8ff982; PR 2119.','HIGH',1,now(),now(),'IG_CURATOR_VALIDATOR_REFACTOR_V2','2119','VALIDATED_TESTED','supabase://programacion.provenance_receipts/187; supabase://programacion.engineering_work_items/461; github://cristhianlujan/claude-persona-lf-patch/pull/2119',now(),now(),'EXECUTION',ARRAY['ENGINEERING_EXECUTOR','SOURCE_RESOLVER']::text[],'STALE_SOURCE_PACK','LIVE_READBACK_AND_NEGATIVE_TEST','M7.13 PAULO-085 completed 5/5, no IG production release','programacion.engineering_plan_units M7.13 source_pack_v1 QUAL_RECEIPT_READBACK'),
(
 gen_random_uuid(),'IG-M713-EXPLAINED-DIVERGENCE-HOLD-001','QUALIFICATION_ASSURANCE','Divergencia explicada no significa autorización para publicar','M4.10 registró 3 divergencias del shadow corpus (screen=58) y tres decisiones vigentes HOLD_BLOCK. Unexplained=0 se puede comprobar, pero el release debe permanecer BLOCKED.','Si el contrato reduce calidad a 0 divergencias sin explicar y cobertura 47/47, puede generar falso green al ignorar adjudicaciones explícitas HOLD_BLOCK.','ADJUDICATED_HOLD_AS_IF_CLEARED_DIVERGENCE','Evaluar por separado (a) divergencias explicadas por adjudicación, (b) holds vigentes, (c) permiso de publicación; con holds>0 no emitir CANDIDATE_EVIDENCED ni release_authorized, aunque cada criterio de cobertura/mutación/adjudicación resulte PASS. Reutilizar QUALIFICATION_FRAMEWORK/CLOSURE_GATE, sin gate propio.','SQL ROLLBACK PR 2119: 47/47 PASS, M4.9 10/10 PASS, M4.10 3 divergencias adjudicadas=PASS, overall BLOCKED y release_authorized=false; al alterar divergencias de 3 a 4 también BLOCKED.','CRITICAL',1,now(),now(),'IG_CURATOR_VALIDATOR_REFACTOR_V2','2119','VALIDATED_TESTED','supabase://public.lf_test_suite_runs/7469c5cb-745b-41aa-80d0-638c32965fa9; transversal.decision_log DEC-IG-M4.10-ADJ-*; github://cristhianlujan/claude-persona-lf-patch/pull/2119',now(),now(),'EXECUTION',ARRAY['QUALIFICATION_VALIDATOR','RELEASE_GOVERNANCE']::text[],'FALSE_GREEN_RISK','LIVE_READBACK_AND_NEGATIVE_TEST','M7.13 PAULO-085 completed 5/5, no IG production release','programacion.fn_ig_release_criteria_controls_v1'),
(
 gen_random_uuid(),'IG-M713-PYTHON-ONE-RUN-TWELVE-CASES-001','TEST_RECEIPT_INTEGRITY','Un script con doce casos no equivale a doce ejecuciones canónicas','La regresión Python de REVERSIBLE_CANDIDATE_VERIFICATION probó 12 escenarios internos, pero el registro canónico representa una ejecución de script y una fila test_run.','Confusión entre cantidad de escenarios internos y total de ejecuciones persistentes; una guardia de admisión inicialmente buscó tests_total>=12 e impedía admitir evidencia real.','SCENARIO_COUNT_CONFUSED_WITH_TEST_RUN_COUNT','Registrar tests_total=1,tests_passed=1 y metadata.scenario_count=12; exigir exact Git blobs, stdout real, exit_code=0, estructura test_run+assertion y bundle VERIFIED. Nunca multiplicar casos para fabricar 12 test_runs ni usar mocks como pruebas de independencia real.','PR 2100: Python 3.10.12 exit 0, 12 escenarios; recibo IG_REVERSIBLE_CANDIDATE_ASSURANCE_2_0_1 PASSED 1/1, scenario_count=12, bundle VERIFIED; hashes blobs fuente y test verificados.','HIGH',1,now(),now(),'IG_CURATOR_VALIDATOR_REFACTOR_V2','2100','VALIDATED_TESTED','supabase://public.lf_test_suite_runs/IG_REVERSIBLE_CANDIDATE_ASSURANCE_2_0_1; sentinelx://scalora-vps/script_job_61555d4492f3496984a6416dcbf6acb0; github://cristhianlujan/claude-persona-lf-patch/pull/2100',now(),now(),'EXECUTION',ARRAY['VALIDATOR','TEST_RUNNER','ASSURANCE']::text[],'RECEIPT_CARDINALITY_MISMATCH','LIVE_READBACK_AND_NEGATIVE_TEST','M7.13 PAULO-085 completed 5/5, no IG production release','programacion.fn_engineering_run_test_receipt_bundle_v1'),
(
 gen_random_uuid(),'IG-M713-BLOCKER-COUNT-DYNAMIC-001','ENGINEERING_TEST_DESIGN','No fijar el número de bloqueos abiertos entre pruebas de varias unidades','La prueba SQL conjunta esperaba cuatro bloqueos abiertos; durante la ejecución otros lotes cerraron M4.12 y M1.A8, quedando dos. La expectativa literal 4 falló por un cambio de estado legítimo.','Prueba multiunidad con número esperado hardcodeado contra un sistema con transiciones concurrentes.','HARDCODED_BLOCKER_COUNT_IN_LIVE_MUTATING_PLAN','Leer la cantidad efectiva desde canonical fn_engineering_effective_open_blocker_count_v1 y disposición ASSIGNED en la misma transacción/snapshot que el prepass; probar contenido y propiedades en lugar de un conteo de foto histórica. Al fallar reanalizar, no repetir ciegamente.','Suite de cinco migraciones PR 2100 pasó en ROLLBACK al sustituir conteo 4 por cálculo dinámico; cero residuos y evidencias Python/consumidores verificadas.','MEDIUM',1,now(),now(),'IG_CURATOR_VALIDATOR_REFACTOR_V2','2100','VALIDATED_TESTED','github://cristhianlujan/claude-persona-lf-patch/pull/2100; programacion.fn_engineering_plan_blocker_repair_prepass_v2',now(),now(),'EXECUTION',ARRAY['ENGINEERING_EXECUTOR','TEST_RUNNER']::text[],'STATIC_EXPECTATION_ON_DYNAMIC_STATE','LIVE_READBACK_AND_NEGATIVE_TEST','M7.13 PAULO-085 completed 5/5, no IG production release','programacion.fn_engineering_effective_open_blocker_count_v1');
 GET DIAGNOSTICS n_new=ROW_COUNT;
 IF n_new<>7 THEN RAISE EXCEPTION 'IG_M713_EKB_INSERT_COUNT_INVALID_%',n_new; END IF;
 UPDATE public.lf_error_knowledge
 SET evidencia=coalesce(evidencia,'') || E'\n[READBACK_20261011_M713_CLOSURE] '
  || 'PR #2100 merged; INDEPENDENT_ASSURANCE 2.0.1; SAFE_CHANGE_ADMISSION 1.0.2; '
  || 'REVERSIBLE_CANDIDATE_VERIFICATION 1.0.3; HUMAN_ESCALATION_ADMISSION 1.0.4. '
  || 'Python script 12 scenarios, 1 canonical run, and SQL joint ROLLBACK; normal admission restored. '
  || 'Self-repair emergency authorization remains CANDIDATO: full disaster-case negative matrix not executed.',
 ultima_vez=now(),updated_at=now(),pr=coalesce(nullif(pr,''),'2100')
 WHERE codigo='ENGINEERING-AUTHORITY-SELF-REPAIR-CIRCULAR-001'
 AND evidencia NOT LIKE '%[READBACK_20261011_M713_CLOSURE]%';
 UPDATE public.lf_error_knowledge
 SET evidencia=coalesce(evidencia,'') || E'\n[READBACK_20261011_M713_CLOSURE] '
  || 'Contract + transversal currentness repaired PR #2100, then scoped M7.13 construction '
  || 'PR #2111, #2113, #2115, #2119 merged/applied/tested. '
  || 'M7.13 PAULO-085 DONE 5/5, 0 open blockers. Release is separate and HOLD_BLOCK persists.',
 ultima_vez=now(),updated_at=now(),pr=coalesce(nullif(pr,''),'2100,2111,2113,2115,2119')
 WHERE codigo='ENGINEERING-BLOCKER-DUAL-SCOPE-REPAIR-001'
 AND evidencia NOT LIKE '%[READBACK_20261011_M713_CLOSURE]%';
 IF (SELECT count(*) FROM public.lf_error_knowledge WHERE codigo=ANY(ARRAY['IG-M713-UNBLOCK-NOT-UNIT-CLOSURE-001','IG-M713-MATERIAL-ASSERTION-RECEIPT-001','IG-M713-FUSED-MUTATION-PROVIDER-001','IG-M713-ASOF-UPSTREAM-NOT-MISSING-001','IG-M713-EXPLAINED-DIVERGENCE-HOLD-001','IG-M713-PYTHON-ONE-RUN-TWELVE-CASES-001','IG-M713-BLOCKER-COUNT-DYNAMIC-001']))<>7
 THEN RAISE EXCEPTION 'IG_M713_EKB_READBACK_COUNT_INVALID'; END IF;
END $ekb$;
